package io.clipbridge.android;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
final class MediaProtocol {
    static final int CHUNK=256*1024;static final long MAX=100L*1024*1024;
    static byte[] hmac(byte[] key,byte[] data)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return mac.doFinal(data);}
    static JSONObject indexConfig(JSONObject c)throws Exception{return new JSONObject(c.toString()).put("key",Protocol.encode(hmac(Protocol.decode(c.getString("key")),"clipbridge:attachments-index:1".getBytes(StandardCharsets.US_ASCII))));}
    static String sealIndex(JSONObject c,JSONObject index)throws Exception{long now=System.currentTimeMillis()/1000;JSONObject payload=new JSONObject(index.toString()).put("created",now).put("expires",now+3600);byte[] nonce=new byte[12];new SecureRandom().nextBytes(nonce);JSONObject e=new JSONObject().put("version",1).put("pair",c.getString("pair")).put("from",c.getString("device")).put("to",c.getString("peer")).put("id",java.util.UUID.randomUUID().toString().replace("-","")).put("clock",now*1000).put("nonce",Protocol.encode(nonce));e.put("data",Protocol.encode(Crypto.transform(Cipher.ENCRYPT_MODE,Protocol.decode(indexConfig(c).getString("key")),nonce,Protocol.header(e),payload.toString().getBytes(StandardCharsets.UTF_8))));return e.toString();}
    static JSONObject openIndex(JSONObject c,String data)throws Exception{JSONObject e=new JSONObject(data);String header=Protocol.header(e);if(!e.getString("pair").equals(c.getString("pair"))||!e.getString("from").equals(c.getString("peer"))||!e.getString("to").equals(c.getString("device")))throw new SecurityException();byte[] nonce=Protocol.decode(e.getString("nonce")),cipher=Protocol.decode(e.getString("data"));if(nonce.length!=12||cipher.length<16||cipher.length>400000)throw new SecurityException();byte[] plain=Crypto.transform(Cipher.DECRYPT_MODE,Protocol.decode(indexConfig(c).getString("key")),nonce,header,cipher);try{JSONObject index=new JSONObject(new String(plain,StandardCharsets.UTF_8));long now=System.currentTimeMillis()/1000,created=index.getLong("created"),expires=index.getLong("expires");JSONArray offers=index.getJSONArray("offers"),decisions=index.getJSONArray("decisions");if(created>now+60||expires<created||expires-created>3600||offers.length()>32||decisions.length()>128)throw new SecurityException();for(int i=0;i<offers.length();i++)validate(offers.getJSONObject(i));for(int i=0;i<decisions.length();i++){JSONObject d=decisions.getJSONObject(i);Protocol.id(d.getString("id"));if(!java.util.Set.of("accepted","rejected","done").contains(d.getString("status")))throw new SecurityException();}return expires<=now?null:index;}finally{java.util.Arrays.fill(plain,(byte)0);}}
    static void validate(JSONObject o)throws Exception{Protocol.id(o.getString("id"));Protocol.id(o.getString("sender"));long size=o.getLong("size");String name=o.getString("name");if(size<0||size>MAX||o.getInt("chunks")!=Math.max(1,(size+CHUNK-1)/CHUNK)||!o.getString("hash").matches("[0-9a-f]{64}")||!java.util.Set.of("image","file").contains(o.getString("kind"))||!java.util.Set.of("offered","ready","cancelled").contains(o.getString("status"))||name.isBlank()||name.length()>180||name.matches(".*[\\p{Cntrl}/\\\\:].*")||name.equals(".")||name.equals("..")||o.getString("mime").length()>100)throw new SecurityException();}
    static String safe(String name){String value=name.replaceAll("[\\p{Cntrl}<>:\"/\\\\|?*]","_").replaceAll("^[ .]+|[ .]+$","");if(value.isEmpty())value="file";return value.substring(0,Math.min(180,value.length()));}
    static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}
    private static byte[] aad(JSONObject c,String id,int part,boolean outgoing)throws Exception{Protocol.id(id);if(part<0||part>=400)throw new SecurityException();String from=c.getString(outgoing?"device":"peer"),to=c.getString(outgoing?"peer":"device");return ("clipbridge:attachment:1:"+c.getString("pair")+":"+from+":"+to+":"+id+":"+part).getBytes(StandardCharsets.US_ASCII);}
    static byte[] encrypt(JSONObject c,String id,int part,byte[] plain)throws Exception{if(plain.length>CHUNK)throw new SecurityException();byte[] aad=aad(c,id,part,true),nonce=new byte[12];new SecureRandom().nextBytes(nonce);byte[] key=hmac(Protocol.decode(c.getString("key")),aad);try{Cipher aes=Cipher.getInstance("AES/GCM/NoPadding");aes.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));aes.updateAAD(aad);byte[] cipher=aes.doFinal(plain),output=new byte[12+cipher.length];System.arraycopy(nonce,0,output,0,12);System.arraycopy(cipher,0,output,12,cipher.length);return output;}finally{java.util.Arrays.fill(key,(byte)0);}}
    static byte[] decrypt(JSONObject c,String id,int part,byte[] cipher)throws Exception{if(cipher.length<28||cipher.length>CHUNK+28)throw new SecurityException();byte[] aad=aad(c,id,part,false),key=hmac(Protocol.decode(c.getString("key")),aad);try{Cipher aes=Cipher.getInstance("AES/GCM/NoPadding");aes.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(cipher,0,12)));aes.updateAAD(aad);return aes.doFinal(cipher,12,cipher.length-12);}finally{java.util.Arrays.fill(key,(byte)0);}}
}
